    "summary": "يتناول الدرس مفهوم الإضافة كتركيب ينشأ من ضم اسم إلى اسم آخر ليكتسب معنى جديدًا لا يتم إلا بوجود الطرفين معًا؛ حيث يُسمى الأول مضافًا ويُعرب حسب موقعه في الجملة، بينما يُسمى الثاني مضافًا إليه ويكون مجرورًا دائمًا أو في محل جر. ومن أهم خصائص المضاف أنه يُحذف منه التنوين إذا كان مفردًا، وتُحذف نون التثنية أو نون جمع المذكر السالم عند الإضافة، مثل حذف النون في 'عيناك' و'غابتا' و'حارسي الوطن'.\n\nكما يُفصّل الدرس في أحكام الأسماء التي تلازم الإضافة إلى المفرد؛ فـ (كلا وكلتا) تُعربان إعراب الاسم المقصور بالحركات المقدرة إذا أُضيفتا إلى اسم ظاهر كقوله تعالى: ﴿كِلْتَا الْجَنَّتَيْنِ آتَتْ أُكُلَهَا وَلَمْ تَظْلِم مِّنْهُ شَيْئًا﴾ (سورة الكهف: 33)، وتُعربان إعراب الملحق بالمثنى إذا أُضيفتا إلى ضمير. أما الظروف مثل (قبل) و(بعد) فتلازم الإضافة غالبًا وتُنصب على الظرفية، وقد تُقطع عن الإضافة لفظًا فتُبنى على الضم في محل جر كما في قوله تعالى: ﴿لِلَّهِ الْأَمْرُ مِن قَبْلُ وَمِن بَعْدُ﴾ (سورة الروم: 4). وتطرق الدرس أيضًا إلى الظروف التي تلازم الإضافة إلى الجمل كـ (حيث، إذ، إذا) مثل قوله تعالى: ﴿أَسْكِنُوهُنَّ مِنْ حَيْثُ سَكَنْتُم مِّن وُجْدِكُمْ وَلَا تُضَارُّوهُنَّ لِتُضَيِّقُوا عَلَيْهِنَّ﴾ (سورة الطلاق: 6).",
    "keyPoints": [
      "الإضافة تركيب اسمي يتكون من ركنين: المضاف (يُعرب حسب موقعه) والمضاف إليه (يكون مجرورًا دائمًا أو في محل جر).",
      "يُحذف التنوين من المضاف المفرد، وتُحذف نون المثنى ونون جمع المذكر السالم عند الإضافة.",
      "تُعرب (كلا وكلتا) إعراب الاسم المقصور بحركات مقدرة إذا أُضيفتا لاسم ظاهر، وإعراب الملحق بالمثنى إذا أُضيفتا لضمير.",
      "الظرفان (قبل وبعد) يلازمان الإضافة غالبًا، ويُبنيان على الضم إذا قُطعا عن الإضافة لفظًا لا معنىً.",
      "كلمة (وحد) تلازم الإضافة إلى الضمير دائمًا وتُعرب حالاً منصوبة، ولا يجوز إدخال حرف الجر اللام عليها فلا يُقال 'لوحده'.",
      "هناك ظروف تلازم الإضافة إلى الجمل (الاسمية أو الفعلية) وهي (حيث، إذ، إذا)."
    ],
